  B -->|"Có"| C{"Read path khớp deny rule?"}
  C -->|"Có"| X["DENY - lý do vào tool_result"]
  C -->|"Không"| D["PreToolUse hooks<br/>các nguồn chạy song song"]
  D --> E{"Kết quả hook"}
  E -->|"deny hoặc exit 2"| X
  E -->|"lỗi hoặc timeout, onFailure block"| X
  E -->|"ask, chế độ -p"| X
  E -->|"allow"| F{"Deny rule khớp?"}
  E -->|"im lặng, exit 1, timeout"| F
  F -->|"Có"| X
  F -->|"Không"| G{"Ask rule khớp?"}
  G -->|"Có"| P["Cần hỏi"]
  G -->|"Không"| H{"Hook đã allow<br/>hoặc allow rule?"}
  H -->|"Có"| OK["ALLOW - thực thi"]
  H -->|"Không"| M{"Permission mode"}
  M -->|"lệnh chỉ đọc"| OK
  M -->|"default, còn lại"| P
  M -->|"auto, còn lại"| CL{"Classifier<br/>server review hoặc side_query"}
  CL -->|"cho phép"| OK
  CL -->|"chặn"| XD["DENY - reason dạng Category<br/>PermissionDenied, không PermissionRequest"]
  P --> PR["PermissionRequest hooks"]
  PR --> UI{"Có người trả lời?"}
  UI -->|"-p"| X2["DENY - source config<br/>không PermissionDenied"]
  UI -->|"interactive - docs"| Q["Hộp thoại, Notification"]

flowchart LR
  P1["Phase 1: Khảo sát tài liệu<br/>Đọc nguồn nhóm A, B<br/>Nháp view 1–6<br/>Gắn nhãn giả thuyết"] --> G1{{"G1: Mỗi RQ có<br/>giả thuyết và nguồn dẫn"}}
  G1 --> P2["Phase 2: Gắn công cụ đo<br/>Repo mẫu, hook logger<br/>Xác nhận trường đo<br/>Script phân tích"] --> G2{{"G2: Log đủ mọi hook event<br/>của init và prompt"}}
  G2 --> P3["Phase 3: Dựng lại mô hình<br/>Chạy E1–E12<br/>Dựng D1–D8 từ log<br/>Ghi lại dự đoán sai"] --> G3{{"G3: 8 artifact P0<br/>khớp với log"}}
  G3 --> P4["Phase 4: Nghiệm thu<br/>Làm P1 (D9–D15)<br/>Review với 2 engineer<br/>Chốt phiên bản"] --> G4{{"G4: Đạt bài kiểm tra<br/>ở mục 2"}}

classDiagram
  class ConversationRecord {
    +string uuid
    +string parentUuid
    +bool isSidechain
    +string type
    +string timestamp
    +string sessionId
    +string cwd
    +string version
    +string entrypoint
  }
  class UserRecord {
    +Message message
    +string promptId
    +bool isMeta
    +bool isCompactSummary
    +object toolUseResult
    +PermissionDecision permissionDecision
  }
  class AssistantRecord {
    +Message message
    +string requestId
    +int apiBlockIndex
    +string effort
  }
  class AttachmentRecord {
    +Attachment attachment
    +string renderedRole
  }
  class SystemRecord {
    +string subtype
    +string level
  }
  class CompactBoundary {
    +string logicalParentUuid
    +CompactMetadata compactMetadata
  }
  class StopHookSummary {
    +int hookCount
    +bool preventedContinuation
  }
  class Usage {
    +int input_tokens
    +int cache_creation_input_tokens
    +int cache_read_input_tokens
    +int output_tokens
  }
  class CompactMetadata {
    +string trigger
    +int preTokens
    +int postTokens
    +int durationMs
  }
  class StateRecord {
    +string type
    +string sessionId
  }
  class CostState {
    +float totalCostUSD
    +int startTime
    +map modelUsage
  }
  class LastPrompt {
    +string leafUuid
  }
  ConversationRecord <|-- UserRecord
  ConversationRecord <|-- AssistantRecord
  ConversationRecord <|-- AttachmentRecord
  ConversationRecord <|-- SystemRecord
  SystemRecord <|-- CompactBoundary
  SystemRecord <|-- StopHookSummary
  StateRecord <|-- CostState
  StateRecord <|-- LastPrompt
  AssistantRecord --> Usage
  CompactBoundary --> CompactMetadata
  ConversationRecord --> ConversationRecord : parentUuid

flowchart TD
  Q1{"Phải cưỡng chế, không phụ thuộc model?"} -->|"Có"| Q2{"Quyết định tĩnh theo tool, path, lệnh?"}
  Q2 -->|"Có"| R1["Permission rule - deny hoặc ask"]
  Q2 -->|"Không"| R2["Hook, onFailure block"]
  Q1 -->|"Không"| Q3{"Cần ở mọi request?"}
  Q3 -->|"Có"| R3["CLAUDE.md gốc"]
  Q3 -->|"Không"| Q4{"Gắn với vùng file?"}
  Q4 -->|"Có"| R4["Rule có paths"]
  Q4 -->|"Không"| Q5{"Là quy trình hoặc tri thức dùng thỉnh thoảng?"}
  Q5 -->|"Có"| R5["Skill, gọi bằng slash khi cần chắc"]
  Q5 -->|"Không"| Q6{"Cần dữ liệu hệ thống ngoài?"}
  Q6 -->|"Có"| R6["MCP"]
  Q6 -->|"Không"| R7["Subagent nếu đọc nhiều, hoặc hook inject context"]

